+    }
+
+    .form-field {
+      padding: 20px;
+      border-radius: 16px;
+      background: rgba(255, 255, 255, 0.03);
+      border: 1px solid rgba(255, 255, 255, 0.07);
+    }
+
+    fieldset {
+      margin: 0;
+      padding: 0;
+      border: 0;
+    }
+
+    legend {
+      padding: 0;
+      margin-bottom: 14px;
+      font-size: 1.05rem;
+      font-weight: 600;
+    }
+
+    .hint {
+      margin: 0 0 18px;
+      color: var(--muted);
+      font-size: 0.95rem;
+    }
+
+    .options {
+      display: grid;
+      gap: 12px;
+      margin: 0;
+      padding: 0;
+      list-style: none;
+    }
+
+    .option {
+      position: relative;
+    }
+
+    .option input {
+      position: absolute;
+      opacity: 0;
+      inset: 0;
+      pointer-events: none;
+    }
+
+    .option label {
+      display: flex;
+      align-items: center;
+      gap: 12px;
+      padding: 14px 16px;
+      border-radius: 14px;
+      background: var(--panel-2);
+      border: 1px solid var(--border);
+      cursor: pointer;
+      transition: border-color 0.2s ease, transform 0.2s ease, box-shadow 0.2s ease;
+    }
+
+    .option label::before {
+      content: "";
+      width: 18px;
+      height: 18px;
+      border-radius: 50%;
+      border: 2px solid #7283aa;
+      flex: 0 0 auto;
+      box-shadow: inset 0 0 0 4px transparent;
+      transition: border-color 0.2s ease, box-shadow 0.2s ease, background 0.2s ease;
+    }
+
+    .option input:checked + label {
+      border-color: rgba(124, 156, 255, 0.8);
+      box-shadow: 0 0 0 4px var(--focus);
+      background: rgba(124, 156, 255, 0.12);
+    }
+
+    .option input:checked + label::before {
+      border-color: var(--accent);
+      box-shadow: inset 0 0 0 5px var(--accent);
+    }
+
+    .option input:focus-visible + label {
+      outline: 2px solid var(--accent);
+      outline-offset: 2px;
+    }
+
+    .option label:hover {
+      transform: translateY(-1px);
+      border-color: rgba(124, 156, 255, 0.5);
+    }
+
+    .actions {
+      display: flex;
+      gap: 12px;
+      margin-top: 20px;
+      align-items: center;
+    }
+
+    button {
+      appearance: none;
+      border: 0;
+      border-radius: 12px;
+      background: linear-gradient(180deg, var(--accent-strong), var(--accent));
+      color: #08101f;
+      font: inherit;
+      font-weight: 700;
+      padding: 12px 18px;
+      cursor: pointer;
+      box-shadow: 0 12px 28px rgba(124, 156, 255, 0.22);
+      transition: transform 0.2s ease, box-shadow 0.2s ease;
+    }
+
+    button:hover {
+      transform: translateY(-1px);
+      box-shadow: 0 16px 30px rgba(124, 156, 255, 0.28);
+    }
+
+    button:focus-visible {
+      outline: 3px solid var(--focus);
+      outline-offset: 3px;
+    }
+
+    .status {
+      min-height: 1.25em;
+      color: var(--success);
+      font-size: 0.95rem;
+    }
+
+    .visually-hidden {
+      position: absolute;
+      width: 1px;
+      height: 1px;
+      padding: 0;
+      margin: -1px;
+      overflow: hidden;
+      clip: rect(0, 0, 0, 0);
+      white-space: nowrap;
+      border: 0;
+    }
+  </style>
+</head>
+<body>
+  <main class="card">
+    <p class="eyebrow">Preferences</p>
+    <h1>Notification settings</h1>
+
+    <form id="notification-form" novalidate>
+      <div class="form-field">
+        <fieldset>
+          <legend>How do you prefer to receive notifications?</legend>
+          <p class="hint">Choose one option to continue.</p>
+
+          <ul class="options" role="radiogroup" aria-labelledby="notification-question">
+            <li class="option">
+              <input type="radio" id="email" name="notification" value="Email" required />
+              <label for="email">Email</label>
+            </li>
+            <li class="option">
+              <input type="radio" id="sms" name="notification" value="SMS" />
+              <label for="sms">SMS</label>
+            </li>
+            <li class="option">
+              <input type="radio" id="push" name="notification" value="Push Notifications" />
+              <label for="push">Push Notifications</label>
+            </li>
+          </ul>
+        </fieldset>
+      </div>
+
+      <div class="actions">
+        <button type="submit">Submit</button>
+        <p class="status" id="status" aria-live="polite"></p>
+      </div>
+    </form>
+  </main>
+
+  <script>
+    const form = document.getElementById('notification-form');
+    const status = document.getElementById('status');
+
+    form.addEventListener('submit', (event) => {
+      event.preventDefault();
+
+      const selected = form.querySelector('input[name="notification"]:checked');
+      if (!selected) {
+        status.textContent = 'Please select a notification preference.';
+        return;
+      }
+
+      status.textContent = `Saved preference: ${selected.value}.`;
+    });
+  </script>
+</body>
+</html>
*** End Patch
