      --bg: #0b1020;
      --panel: #121a2f;
      --panel-2: #16213a;
      --text: #e8eefc;
      --muted: #a6b3d1;
      --accent: #7c9cff;
      --accent-strong: #9db3ff;
      --border: #263353;
