      border-radius: 20px;
      box-shadow: 0 18px 50px rgba(0, 0, 0, 0.38);
      padding: 32px;
    }

    .eyebrow {
      margin: 0 0 8px;
      color: var(--accent-strong);
      font-size: 0.9rem;
      letter-spacing: 0.08em;
      text-transform: uppercase;
    }

    h1 {
      margin: 0 0 20px;
      font-size: clamp(1.6rem, 2.5vw, 2.1rem);
      line-height: 1.2;
    }

    .form-field {
      padding: 20px;
      border-radius: 16px;
      background: rgba(255, 255, 255, 0.03);
      border: 1px solid rgba(255, 255, 255, 0.07);
    }

    fieldset {
      margin: 0;
      padding: 0;
      border: 0;
    }

    legend {
      padding: 0;
      margin-bottom: 14px;
      font-size: 1.05rem;
      font-weight: 600;
    }

    .hint {
      margin: 0 0 18px;
      color: var(--muted);
      font-size: 0.95rem;
    }

    .options {
      display: grid;
      gap: 12px;
      margin: 0;
      padding: 0;
      list-style: none;
    }

    .option {
      position: relative;
    }

    .option input {
      position: absolute;
      opacity: 0;
      inset: 0;
      pointer-events: none;
    }

    .option label {
      display: flex;
      align-items: center;
      gap: 12px;
      padding: 14px 16px;
      border-radius: 14px;
      background: var(--panel-2);
      border: 1px solid var(--border);
      cursor: pointer;
      transition: border-color 0.2s ease, transform 0.2s ease, box-shadow 0.2s ease;
    }

    .option label::before {
      content: "";
      width: 18px;
      height: 18px;
      border-radius: 50%;
      border: 2px solid #7283aa;
      flex: 0 0 auto;
      box-shadow: inset 0 0 0 4px transparent;
      transition: border-color 0.2s ease, box-shadow 0.2s ease, background 0.2s ease;
    }

    .option input:checked + label {
      border-color: rgba(124, 156, 255, 0.8);
      box-shadow: 0 0 0 4px var(--focus);
      background: rgba(124, 156, 255, 0.12);
    }

    .option input:checked + label::before {
      border-color: var(--accent);
      box-shadow: inset 0 0 0 5px var(--accent);
    }

    .option input:focus-visible + label {
      outline: 2px solid var(--accent);
      outline-offset: 2px;
    }

    .option label:hover {
      transform: translateY(-1px);
      border-color: rgba(124, 156, 255, 0.5);
    }

    .actions {
      display: flex;
      gap: 12px;
      margin-top: 20px;
      align-items: center;
    }

    button {
      appearance: none;
      border: 0;
